            ["guide.body.target_slot"] = "Platz {slot} - {name}",
            ["guide.body.target_slot_unnamed"] = "Platz {slot}",
            ["guide.body.target_unavailable"] = "! Deine Saved Builds konnten nicht gelesen werden.",
            ["guide.body.target_unavailable_body"] = "Nexus hat nicht geantwortet. Vielleicht lädt es nach dem Login noch. Nichts hat sich geändert.",
            ["guide.body.welcome_body"] = "Diese Anleitung verknüpft eine Wunschliste mit einem Saved Build und zeigt dir dann eine Beispiel-Empfehlung.",
            ["guide.body.welcome_body_replay"] = "Die Anleitung erneut zu starten setzt nichts zurück. Sie prüft neu, was jetzt eingestellt ist, und du kannst alles ändern.",
            ["guide.body.welcome_paths_existing_desc"] = "Richte einen deiner Saved Builds auf eine Wunschliste aus. Du siehst zuerst, was ersetzt wird.",
            ["guide.body.welcome_paths_explore_desc"] = "Sieh dir an, wie Empfehlungen und Auto funktionieren. Nichts wird eingerichtet oder geändert.",
            ["guide.body.welcome_paths_new_desc"] = "Lege eine Wunschliste an und gib ihr einen Build-Platz. Etwa 3 Minuten.",
            ["guide.body.why_assign"] = "Sobald beide verknüpft sind, folgen Empfehlungen deiner Wunschliste für den Build, den du spielst.",
            ["guide.body.why_auto"] = "Auto kann für dich handeln. Es ist optional.",
            ["guide.body.why_manual"] = "Darauf zeigt Nexus, während du würfelst.",
            ["guide.body.why_summary"] = "Sieh, was erledigt und was noch offen ist.",
            ["guide.body.why_target"] = "Ein Saved Build ist der Build-Platz, den das Spiel lädt. Wähle, welcher Saved Build deine Wunschliste nutzen soll.",
            ["guide.body.why_welcome"] = "Nexus zeigt auf Echos aus einer Wunschliste, die du wählst. Im Spiel ändert sich nichts, bis du einen Schritt bestätigst.",
