            ["help.error.assign_after_startup"] = "Asignar lista de deseos se abre cuando termina el inicio (consulta el panel de carga). No se ha abierto ni asignado nada.",
            ["help.error.assignment_route_unavailable"] = "La ruta de asignación protegida no está disponible. No se ha abierto ni asignado nada.",
            ["help.error.automation_settings_after_startup"] = "Los ajustes de automatización se abren cuando termina el inicio (consulta el panel de carga). No se ha abierto ni cambiado nada.",
            ["help.error.automation_settings_did_not_open"] = "Los ajustes de automatización no se abrieron. No se ha cambiado nada.",
            ["help.error.automation_settings_unavailable"] = "Los ajustes de automatización no están disponibles. No se ha abierto ni cambiado nada.",
            ["help.error.checklist_unavailable"] = "La lista de comprobación de la configuración no está disponible.",
            ["help.error.editor_after_startup"] = "El editor de listas de deseos se abre cuando termina el inicio (consulta el panel de carga). No se ha abierto nada.",
            ["help.error.editor_did_not_open"] = "El editor de listas de deseos no se abrió. La ayuda sigue aquí; inténtalo de nuevo cuando termine el inicio.",
            ["help.error.editor_unavailable"] = "El editor de listas de deseos no está disponible.",
            ["help.error.guide_unavailable"] = "La configuración guiada no está disponible.",
            ["help.error.guide_unavailable_now"] = "La configuración guiada no está disponible ahora mismo.",
            ["help.error.guide_warning_open"] = "La configuración guiada no se abrió. Responde al aviso abierto y vuelve a abrir la configuración guiada.",
            ["help.error.journal_route_unavailable"] = "La ruta del Echo Journal no está disponible. No se ha asignado nada.",
            ["help.error.logs_after_startup"] = "El visor de registros se abre cuando termina el inicio (consulta el panel de carga). No se ha abierto nada.",
            ["help.error.logs_did_not_open"] = "El visor de registros no se abrió.",
            ["help.error.logs_unavailable"] = "El visor de registros no está disponible.",
            ["help.error.orbs_did_not_open"] = "La ventana de Orb no se abrió. No se ha gastado nada.",
            ["help.error.orbs_unavailable"] = "La ventana de Orb no está disponible. No se ha gastado nada.",
            ["help.error.progression_button_missing"] = "No se encontró el botón Character Progression del juego. No se ha abierto ni asignado nada.",
            ["help.error.setup_unavailable_now"] = "Configuración / Bienvenida no está disponible ahora mismo.",
            ["help.error.setup_unavailable_yet"] = "Configuración / Bienvenida aún no está disponible.",
            ["help.error.setup_warning_open"] = "Configuración / Bienvenida no se abrió. Responde al aviso abierto (Sí o No) y vuelve a abrirla.",
            ["help.error.support_did_not_open"] = "El informe de soporte no se abrió. Escribe /nexus report.",
            ["help.error.support_unavailable"] = "El informe de soporte no está disponible. Escribe /nexus report.",
