            ["help.button.wishlist_editor"] = "Edytor listy życzeń",
            ["help.error.assign_after_startup"] = "Przypisz listę życzeń otwiera się po zakończeniu uruchamiania (zobacz panel wczytywania). Nic nie zostało otwarte ani przypisane.",
            ["help.error.assignment_route_unavailable"] = "Chroniona ścieżka przypisania jest niedostępna. Nic nie zostało otwarte ani przypisane.",
            ["help.error.automation_settings_after_startup"] = "Ustawienia automatyzacji otwierają się po zakończeniu uruchamiania (zobacz panel wczytywania). Nic nie zostało otwarte ani zmienione.",
            ["help.error.automation_settings_did_not_open"] = "Ustawienia automatyzacji się nie otworzyły. Nic nie zostało zmienione.",
            ["help.error.automation_settings_unavailable"] = "Ustawienia automatyzacji są niedostępne. Nic nie zostało otwarte ani zmienione.",
            ["help.error.checklist_unavailable"] = "Lista kontrolna konfiguracji jest niedostępna.",
            ["help.error.editor_after_startup"] = "Edytor listy życzeń otwiera się po zakończeniu uruchamiania (zobacz panel wczytywania). Nic nie zostało otwarte.",
            ["help.error.editor_did_not_open"] = "Edytor listy życzeń się nie otworzył. Pomoc pozostaje tutaj; spróbuj ponownie po zakończeniu uruchamiania.",
            ["help.error.editor_unavailable"] = "Edytor listy życzeń jest niedostępny.",
            ["help.error.guide_unavailable"] = "Konfiguracja z przewodnikiem jest niedostępna.",
            ["help.error.guide_unavailable_now"] = "Konfiguracja z przewodnikiem nie jest teraz dostępna.",
            ["help.error.guide_warning_open"] = "Konfiguracja z przewodnikiem się nie otworzyła. Odpowiedz na otwarte ostrzeżenie, a potem otwórz ponownie konfigurację z przewodnikiem.",
            ["help.error.journal_route_unavailable"] = "Ścieżka do Echo Journal jest niedostępna. Nic nie zostało przypisane.",
            ["help.error.logs_after_startup"] = "Przeglądarka logów otwiera się po zakończeniu uruchamiania (zobacz panel wczytywania). Nic nie zostało otwarte.",
            ["help.error.logs_did_not_open"] = "Przeglądarka logów się nie otworzyła.",
            ["help.error.logs_unavailable"] = "Przeglądarka logów jest niedostępna.",
            ["help.error.orbs_did_not_open"] = "Okno Orbów się nie otworzyło. Nic nie zostało wydane.",
            ["help.error.orbs_unavailable"] = "Okno Orbów jest niedostępne. Nic nie zostało wydane.",
            ["help.error.progression_button_missing"] = "Nie znaleziono przycisku Character Progression w grze. Nic nie zostało otwarte ani przypisane.",
